import { test } from '@playwright/test';

const API_BASE = process.env.SYNCRO_API_BASE_URL ?? 'http://localhost:8080';
const SPAREPARTS_URL = `${API_BASE}/api/v1/spareparts`;
const TAXONOMY_URL = `${API_BASE}/api/v1/sparepart-taxonomy`;

type RoleName = 'SUPER_ADMIN' | 'MANAGE' | 'VIEWER';

type TaxonomyRefs = {
  categoryId: string;
  brandId: string;
  kindId: string;
  typeId: string;
};

function authHeaders(role: RoleName) {
  return {
    Authorization: `Bearer ${process.env[`SYNCRO_ATDD_${role}_TOKEN`] ?? `${role.toLowerCase()}-token-red-phase`}`,
    'Content-Type': 'application/json',
  };
}

function sparepartPayload(overrides: Partial<TaxonomyRefs & { code: string; name: string }> = {}) {
  return {
    code: overrides.code ?? `BRG-${Date.now()}`,
    name: overrides.name ?? `Bearing ${Date.now()}`,
    categoryId: overrides.categoryId ?? '11111111-1111-4111-8111-111111111111',
    brandId: overrides.brandId ?? '22222222-2222-4222-8222-222222222222',
    kindId: overrides.kindId ?? '33333333-3333-4333-8333-333333333333',
    typeId: overrides.typeId ?? '44444444-4444-4444-8444-444444444444',
  };
}

test.describe('Story 2.5 ATDD API RED-PHASE scaffold: manage spareparts', () => {
  test.skip('2.5-ATDD-API-001 P0 SUPER_ADMIN creates sparepart with CATEGORY, BRAND, KIND, TYPE taxonomy refs and sees it in list', async ({ request }) => {
    const payload = sparepartPayload({ code: 'BRG-6205-ZZ', name: 'Bearing 6205 ZZ' });
    await request.post(SPAREPARTS_URL, { headers: authHeaders('SUPER_ADMIN'), data: payload });
    await request.get(SPAREPARTS_URL, { headers: authHeaders('SUPER_ADMIN') });
  });

  test.skip('2.5-ATDD-API-002 P0 MANAGE creates sparepart and VIEWER can read list/detail as global master data', async ({ request }) => {
    const payload = sparepartPayload({ code: 'BLT-M8-30', name: 'Bolt M8 x 30' });
    await request.post(SPAREPARTS_URL, { headers: authHeaders('MANAGE'), data: payload });
    await request.get(SPAREPARTS_URL, { headers: authHeaders('VIEWER') });
    await request.get(`${SPAREPARTS_URL}/00000000-0000-4000-8000-000000000025`, { headers: authHeaders('VIEWER') });
  });

  test.skip('2.5-ATDD-API-003 P0 rejects create when required taxonomy references are missing, null, unknown, or wrong dimension', async ({ request }) => {
    await request.post(SPAREPARTS_URL, { headers: authHeaders('MANAGE'), data: sparepartPayload({ categoryId: undefined as unknown as string }) });
    await request.post(SPAREPARTS_URL, { headers: authHeaders('MANAGE'), data: { ...sparepartPayload(), brandId: null } });
    await request.post(SPAREPARTS_URL, { headers: authHeaders('MANAGE'), data: sparepartPayload({ kindId: 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' }) });
    await request.post(SPAREPARTS_URL, { headers: authHeaders('MANAGE'), data: sparepartPayload({ typeId: '11111111-1111-4111-8111-111111111111' }) });
  });

  test.skip('2.5-ATDD-API-004 P0 rejects update when taxonomy refs are unknown or wrong dimension using safe not-found or validation shape', async ({ request }) => {
    const sparepartId = '00000000-0000-4000-8000-000000000026';
    await request.put(`${SPAREPARTS_URL}/${sparepartId}`, { headers: authHeaders('SUPER_ADMIN'), data: sparepartPayload({ categoryId: 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb' }) });
    await request.put(`${SPAREPARTS_URL}/${sparepartId}`, { headers: authHeaders('SUPER_ADMIN'), data: sparepartPayload({ brandId: '33333333-3333-4333-8333-333333333333' }) });
  });

  test.skip('2.5-ATDD-API-005 P0 rejects blank code/name, over-length values, malformed JSON, and invalid UUID values safely', async ({ request }) => {
    await request.post(SPAREPARTS_URL, { headers: authHeaders('MANAGE'), data: sparepartPayload({ code: '   ', name: 'Valid Pump Seal' }) });
    await request.post(SPAREPARTS_URL, { headers: authHeaders('MANAGE'), data: sparepartPayload({ code: 'X'.repeat(65), name: 'Valid Pump Seal' }) });
    await request.post(SPAREPARTS_URL, { headers: authHeaders('MANAGE'), data: sparepartPayload({ code: 'SEAL-001', name: ' '.repeat(3) }) });
    await request.post(SPAREPARTS_URL, { headers: { ...authHeaders('MANAGE'), 'Content-Type': 'application/json' }, data: '{ malformed-json' });
    await request.get(`${SPAREPARTS_URL}/not-a-uuid`, { headers: authHeaders('MANAGE') });
  });

  test.skip('2.5-ATDD-API-006 P0 rejects duplicate code or name regardless casing and surrounding whitespace on create and update', async ({ request }) => {
    await request.post(SPAREPARTS_URL, { headers: authHeaders('SUPER_ADMIN'), data: sparepartPayload({ code: 'FLT-OIL-01', name: 'Oil Filter Primary' }) });
    await request.post(SPAREPARTS_URL, { headers: authHeaders('SUPER_ADMIN'), data: sparepartPayload({ code: '  flt-oil-01  ', name: 'Oil Filter Secondary' }) });
    await request.post(SPAREPARTS_URL, { headers: authHeaders('SUPER_ADMIN'), data: sparepartPayload({ code: 'FLT-OIL-02', name: '  oil filter primary  ' }) });
    await request.put(`${SPAREPARTS_URL}/00000000-0000-4000-8000-000000000027`, { headers: authHeaders('SUPER_ADMIN'), data: sparepartPayload({ code: 'flt-oil-01', name: 'Unique Filter Name' }) });
  });

  test.skip('2.5-ATDD-API-007 P1 allows same taxonomy combination for distinct spareparts when code and name are unique', async ({ request }) => {
    const refs = { categoryId: '11111111-1111-4111-8111-111111111111', brandId: '22222222-2222-4222-8222-222222222222', kindId: '33333333-3333-4333-8333-333333333333', typeId: '44444444-4444-4444-8444-444444444444' };
    await request.post(SPAREPARTS_URL, { headers: authHeaders('MANAGE'), data: sparepartPayload({ ...refs, code: 'CHAIN-40-1', name: 'Roller Chain 40 A' }) });
    await request.post(SPAREPARTS_URL, { headers: authHeaders('MANAGE'), data: sparepartPayload({ ...refs, code: 'CHAIN-40-2', name: 'Roller Chain 40 B' }) });
  });

  test.skip('2.5-ATDD-API-008 P0 lists spareparts with predictable ordering and filters by category, brand, kind, type, and code/name search', async ({ request }) => {
    await request.get(`${SPAREPARTS_URL}?categoryId=11111111-1111-4111-8111-111111111111&brandId=22222222-2222-4222-8222-222222222222`, { headers: authHeaders('VIEWER') });
    await request.get(`${SPAREPARTS_URL}?kindId=33333333-3333-4333-8333-333333333333&typeId=44444444-4444-4444-8444-444444444444`, { headers: authHeaders('VIEWER') });
    await request.get(`${SPAREPARTS_URL}?search=bearing`, { headers: authHeaders('VIEWER') });
    await request.get(`${SPAREPARTS_URL}?search=BRG-6205`, { headers: authHeaders('VIEWER') });
  });

  test.skip('2.5-ATDD-API-009 P0 updates bounded fields and taxonomy references then returns updated taxonomy labels', async ({ request }) => {
    const sparepartId = '00000000-0000-4000-8000-000000000028';
    await request.put(`${SPAREPARTS_URL}/${sparepartId}`, { headers: authHeaders('MANAGE'), data: sparepartPayload({ code: 'SEAL-PUMP-02', name: 'Pump Mechanical Seal Updated', categoryId: '55555555-5555-4555-8555-555555555555' }) });
    await request.get(`${SPAREPARTS_URL}/${sparepartId}`, { headers: authHeaders('MANAGE') });
  });

  test.skip('2.5-ATDD-API-010 P0 deletes sparepart without dependent installations and subsequent get returns safe not found', async ({ request }) => {
    const sparepartId = '00000000-0000-4000-8000-000000000029';
    await request.delete(`${SPAREPARTS_URL}/${sparepartId}`, { headers: authHeaders('SUPER_ADMIN') });
    await request.get(`${SPAREPARTS_URL}/${sparepartId}`, { headers: authHeaders('SUPER_ADMIN') });
  });

  test.skip('2.5-ATDD-API-011 P0 returns safe 409 conflict when deleting sparepart referenced by installed spareparts', async ({ request }) => {
    const installedSparepartDependencyTargetId = '00000000-0000-4000-8000-000000000030';
    await request.delete(`${SPAREPARTS_URL}/${installedSparepartDependencyTargetId}`, { headers: authHeaders('MANAGE') });
  });

  test.skip('2.5-ATDD-API-012 P0 denies VIEWER create, update, and delete with safe forbidden response', async ({ request }) => {
    await request.post(SPAREPARTS_URL, { headers: authHeaders('VIEWER'), data: sparepartPayload({ code: 'VIEWER-DENIED-01', name: 'Viewer Denied Create' }) });
    await request.put(`${SPAREPARTS_URL}/00000000-0000-4000-8000-000000000031`, { headers: authHeaders('VIEWER'), data: sparepartPayload({ code: 'VIEWER-DENIED-02', name: 'Viewer Denied Update' }) });
    await request.delete(`${SPAREPARTS_URL}/00000000-0000-4000-8000-000000000031`, { headers: authHeaders('VIEWER') });
  });

  test.skip('2.5-ATDD-API-013 P0 unauthenticated requests to every sparepart endpoint return existing safe authentication error shape', async ({ request }) => {
    await request.get(SPAREPARTS_URL);
    await request.get(`${SPAREPARTS_URL}/00000000-0000-4000-8000-000000000032`);
    await request.post(SPAREPARTS_URL, { data: sparepartPayload({ code: 'NOAUTH-01', name: 'No Auth Create' }) });
    await request.put(`${SPAREPARTS_URL}/00000000-0000-4000-8000-000000000032`, { data: sparepartPayload({ code: 'NOAUTH-02', name: 'No Auth Update' }) });
    await request.delete(`${SPAREPARTS_URL}/00000000-0000-4000-8000-000000000032`);
  });

  test.skip('2.5-ATDD-API-014 P1 returns global non-plant-scoped sparepart master data for MANAGE and VIEWER despite plant assignment limits', async ({ request }) => {
    await request.get(SPAREPARTS_URL, { headers: authHeaders('MANAGE') });
    await request.get(SPAREPARTS_URL, { headers: authHeaders('VIEWER') });
  });

  test.skip('2.5-ATDD-API-015 P1 rejects invalid UUID query filters and unknown sparepart detail id safely', async ({ request }) => {
    await request.get(`${SPAREPARTS_URL}?categoryId=not-a-uuid`, { headers: authHeaders('VIEWER') });
    await request.get(`${SPAREPARTS_URL}/99999999-9999-4999-8999-999999999999`, { headers: authHeaders('VIEWER') });
  });
});
